const settleWorkOrder = `-- name: SettleWorkOrder :one
UPDATE manufacturing.work_orders w
SET status = CASE
        WHEN EXISTS (SELECT 1 FROM manufacturing.time_logs l
                     WHERE l.work_order_id = w.id AND l.ended_at IS NULL AND l.kind = 'productive') THEN 'in_progress'
        WHEN w.started_at IS NOT NULL THEN 'paused'
        ELSE w.status END,
    revision = w.revision + 1
WHERE w.id = $1 AND w.status NOT IN ('done', 'cancelled')
RETURNING id, order_id, operation_id, sequence, name, work_center_id, setup_minutes, cleanup_minutes, minutes_per_cycle, capacity, time_efficiency, machine_rate, labour_rate, instructions, expected_minutes, planned_start, planned_finish, status, started_at, finished_at, revision
`

// SettleWorkOrder is a work order's state from its logs (M27, M29a): in
// progress while a productive log is open, else paused once started; a
// work order never started, done or cancelled keeps its state.
func (q *Queries) SettleWorkOrder(ctx context.Context, id int64) (ManufacturingWorkOrder, error) {
	row := q.db.QueryRow(ctx, settleWorkOrder, id)
	var i ManufacturingWorkOrder
	err := row.Scan(
		&i.ID,
		&i.OrderID,
		&i.OperationID,
		&i.Sequence,
		&i.Name,
		&i.WorkCenterID,
		&i.SetupMinutes,
		&i.CleanupMinutes,
		&i.MinutesPerCycle,
		&i.Capacity,
		&i.TimeEfficiency,
		&i.MachineRate,
		&i.LabourRate,
		&i.Instructions,
		&i.ExpectedMinutes,
		&i.PlannedStart,
		&i.PlannedFinish,
		&i.Status,
		&i.StartedAt,
		&i.FinishedAt,
		&i.Revision,
	)
	return i, err
}

