const userLogOverlaps = `-- name: UserLogOverlaps :one
SELECT EXISTS (
    SELECT 1 FROM manufacturing.time_logs
    WHERE user_id = $1 AND id <> $2
      AND started_at < $3::timestamptz
      AND COALESCE(ended_at, 'infinity'::timestamptz) > $4::timestamptz)
`

type UserLogOverlapsParams struct {
	UserID    *uuid.UUID
	ID        int64
	EndedAt   time.Time
	StartedAt time.Time
}

// UserLogOverlaps reports whether the user has another log, open or closed,
// overlapping started_at … ended_at (log_overlaps, M29a).
func (q *Queries) UserLogOverlaps(ctx context.Context, arg UserLogOverlapsParams) (bool, error) {
	row := q.db.QueryRow(ctx, userLogOverlaps,
		arg.UserID,
		arg.ID,
		arg.EndedAt,
		arg.StartedAt,
	)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const workCenterQueue = `-- name: WorkCenterQueue :many
SELECT w.id FROM manufacturing.work_orders w JOIN manufacturing.orders o ON o.id = w.order_id
WHERE w.work_center_id = $1
  AND w.status IN ('ready', 'in_progress', 'paused')
  AND o.status IN ('confirmed', 'in_progress')
ORDER BY w.planned_start ASC NULLS LAST, (o.priority = 'urgent') DESC, o.due_date ASC NULLS LAST,
         o.number, o.suffix, w.sequence, w.id
LIMIT 500
`

// WorkCenterQueue is the work center's queue (M31): its ready, in-progress
// and paused work orders of open orders, by planned start, then the order's
// priority, then its due date.
func (q *Queries) WorkCenterQueue(ctx context.Context, workCenterID int64) ([]int64, error) {
	rows, err := q.db.Query(ctx, workCenterQueue, workCenterID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

