const workOrdersTouchedBy = `-- name: WorkOrdersTouchedBy :many
SELECT work_order_id::bigint AS work_order_id, bool_or(ended_at IS NULL)::boolean AS running,
       max(COALESCE(ended_at, started_at))::timestamptz AS last_at
FROM manufacturing.time_logs
WHERE user_id = $1 AND work_order_id IS NOT NULL
  AND started_at < $2::timestamptz
  AND (ended_at IS NULL OR ended_at >= $3::timestamptz)
GROUP BY work_order_id
ORDER BY running DESC, last_at DESC, work_order_id DESC
LIMIT 100
`

type WorkOrdersTouchedByParams struct {
	UserID *uuid.UUID
	ToAt   time.Time
	FromAt time.Time
}

type WorkOrdersTouchedByRow struct {
	WorkOrderID int64
	Running     bool
	LastAt      time.Time
}

// WorkOrdersTouchedBy is the work orders the user logged time on between
// from and to, or still runs: "my work" (M31), the latest first.
func (q *Queries) WorkOrdersTouchedBy(ctx context.Context, arg WorkOrdersTouchedByParams) ([]WorkOrdersTouchedByRow, error) {
	rows, err := q.db.Query(ctx, workOrdersTouchedBy, arg.UserID, arg.ToAt, arg.FromAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []WorkOrdersTouchedByRow
	for rows.Next() {
		var i WorkOrdersTouchedByRow
		if err := rows.Scan(&i.WorkOrderID, &i.Running, &i.LastAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
